## 定向测试设计（静态方案，未执行）

以下测试基于 Node.js 内置 `node:test` + `node:assert` 风格编写，覆盖正常路径、边界、失败和取消场景。

```javascript
import { test } from 'node:test';
import assert from 'node:assert/strict';

// --- 辅助工厂 ---
function makeFetch(pages) {
  let idx = 0;
  return async ({ cursor, signal }) => {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
    const page = pages[idx++];
    if (page instanceof Error) throw page;
    return page;
  };
}

test('正常多页收集 + SameValueZero 去重', async () => {
  const fetchPage = makeFetch([
    { items: [1, 2, NaN], nextCursor: 'c1' },
    { items: [2, NaN, 3], nextCursor: null },
  ]);
  const res = await collectPages(fetchPage, { maxPages: 5 });
  // SameValueZero: 第二个 2 和第二个 NaN 被去重
  assert.deepStrictEqual(res, [1, 2, NaN, 3]);
});

test('空 items 数组正常返回空结果', async () => {
  const fetchPage = makeFetch([{ items: [], nextCursor: null }]);
  const res = await collectPages(fetchPage, { maxPages: 1 });
  assert.deepStrictEqual(res, []);
});

test('达到 maxPages 且仍有 nextCursor → PAGE_LIMIT', async () => {
  const fetchPage = makeFetch([
    { items: ['a'], nextCursor: 'c1' },
    { items: ['b'], nextCursor: 'c2' },
  ]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 2 }),
    { message: 'PAGE_LIMIT' }
  );
});

test('恰好 maxPages 页且最后一页 nextCursor=null → 正常结束', async () => {
  const fetchPage = makeFetch([
    { items: [1], nextCursor: 'c1' },
    { items: [2], nextCursor: null },
  ]);
  const res = await collectPages(fetchPage, { maxPages: 2 });
  assert.deepStrictEqual(res, [1, 2]);
});

test('响应为 null → INVALID_PAGE', async () => {
  const fetchPage = makeFetch([null]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 1 }),
    { message: 'INVALID_PAGE' }
  );
});

test('响应 items 非数组 → INVALID_PAGE', async () => {
  const fetchPage = makeFetch([{ items: 'not-array', nextCursor: null }]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 1 }),
    { message: 'INVALID_PAGE' }
  );
});

test('signal 已取消 → 立即抛出 AbortError', async () => {
  const controller = new AbortController();
  controller.abort();
  const fetchPage = makeFetch([{ items: [1], nextCursor: null }]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 1, signal: controller.signal }),
    (err) => err.name === 'AbortError'
  );
});

test('fetchPage 中途抛异常 → 原样透传', async () => {
  const fetchPage = makeFetch([new Error('NETWORK_FAIL')]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 1 }),
    { message: 'NETWORK_FAIL' }
  );
});

test('maxPages 非法 → TypeError', async () => {
  const fetchPage = makeFetch([]);
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 0 }),
    TypeError
  );
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: -1 }),
    TypeError
  );
  await assert.rejects(
    () => collectPages(fetchPage, { maxPages: 1.5 }),
    TypeError
  );
});
```

### 测试覆盖矩阵

| 场景 | 初态 | 操作 | 预期判据 |
|---|---|---|---|
| 多页 + 去重 | 两页数据含重复项 | 正常调用 | 返回去重数组，顺序一致 |
| 空页 | items=[] | 正常调用 | 返回 [] |
| 超限 | maxPages=2，3页游标 | 拉取第2页后发现 nextCursor | 抛 PAGE_LIMIT |
| 恰好满页 | maxPages=2，第2页 nextCursor=null | 正常拉取 | 正常返回不抛错 |
| 非法响应 | 返回 null / items 非数组 | 调用 fetchPage | 抛 INVALID_PAGE |
| 已取消 | signal.aborted=true | 进入循环 | 抛 AbortError，不调 fetchPage |
| 网络异常 | fetchPage 抛错 | await fetchPage | 原样透传错误 |
| 参数非法 | maxPages=0/-1/1.5 | 入口校验 | 抛 TypeError |

---

## 风险与未完成项

- **未执行声明**：本轮受约束不调用工具，以上代码与测试均为静态交付，未在运行时实际执行。
- **+0 / -0 去重**：SameValueZero 将 `+0` 与 `-0` 视为相同，`Set` 原生支持此行为；若业务需区分正负零，需改用自定义 Map 键策略。
- **内存预算**：当单页 items 极大或总唯一值极多时，`Set` 与 `result` 数组占用 O(U) 内存；若有明确内存上限约束，需引入外部存储或流式消费模式，当前合同未给出该约束故保持最小实现。

